import * as C from './core.js';
import * as S from './storage.js';
import * as A from './api.js';
import * as B from './bridge.js';

const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',auction:'♧',feed:'♡',inbox:'✉',bench:'▣',me:'☺'};
const tabs=[['home','橱窗'],['auction','稿拍'],['feed','广场'],['inbox','消息'],['bench','工作台'],['me','我的']];
const status={quoted:'待确认',working:'绘制中',review:'待验收',complete:'已完成',cancelled:'已取消'};
const app=document.createElement('section');app.id='hy-app';app.hidden=true;app.setAttribute('aria-label','绘约虚拟约稿平台');document.body.append(app);
const launcher=document.createElement('button');launcher.id='hy-launcher';launcher.type='button';launcher.textContent='✿ 绘约';launcher.title='打开绘约虚拟约稿平台';document.body.append(launcher);
let w,route={page:'home'},filter='',feedFilter='全部',search='',opened=false,saveChain=Promise.resolve(),actionBusy=false,modalCleanup=null;
const running=new Map(),urls=new Map();let epoch=0;
async function completeSafe(...args){const started=epoch;const result=await A.complete(...args);if(started!==epoch)throw Error('当前世界已经切换，已放弃上个世界的返回结果');return result;}
async function putAssetSafe(...args){const started=epoch;const result=await S.putAsset(...args);if(started!==epoch)throw Error('当前世界已经切换，请在当前世界重新上传');return result;}
let globalId;
try{globalId=localStorage.getItem('huiyue-world')||C.uid();localStorage.setItem('huiyue-world',globalId);}catch{globalId='huiyue-default';}
const btn=(act,label,id='',cls='')=>`<button type="button" class="${cls}" data-act="${act}" data-id="${E(id)}">${label}</button>`;
const tag=s=>`<span class="hy-tag">${E(s)}</span>`;
const img=(id,cls='',fallback='✿')=>id?`<img class="${cls}" data-image="${E(id)}" alt="图片" loading="lazy">`:`<span class="hy-image-fallback ${cls}">${fallback}</span>`;
const empty=(s,extra='')=>`<div class="hy-empty"><span>✧</span><p>${E(s)}</p>${extra}</div>`;
const money=n=>Number(n).toLocaleString('zh-CN');
const profile=()=>w.accounts[w.role];
const appearance=()=>({...w.settings,...(!w.settings.sharedProfile?profile().appearance||{}:{})});
const artistName=id=>id==='self'?w.accounts.artist.name:w.artists.find(a=>a.id===id)?.name||'未知画师';
const getOrder=id=>C.order(w,id);
function toast(s,error=false){let el=document.getElementById('hy-toast');if(!el){el=document.createElement('div');el.id='hy-toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=s;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,error?8000:3500);}
function persist(){const snapshot=structuredClone(w);saveChain=saveChain.catch(()=>{}).then(()=>S.saveWorld(snapshot));B.injectSummary(w);return saveChain;}
function go(page,id){route={page,id};filter='';render();}
async function hydrate(root=app){for(const el of root.querySelectorAll('[data-image]')){const id=el.dataset.image;try{let u=urls.get(id);if(!u){const a=await S.getAsset(id);if(!a)continue;u=URL.createObjectURL(a.blob);urls.set(id,u);}if(el.isConnected){if(el.tagName==='IMG')el.src=u;else el.style.backgroundImage=`url("${u}")`;}}catch{el.alt='图片读取失败';}}}
function themes(){const settings=appearance();const colors={sky:['#75a8c6','#f3f7fb','#ffffff','#263545'],rose:['#c48f9e','#fcf5f6','#ffffff','#503940'],mint:['#75a99a','#f0f8f4','#ffffff','#2e453d'],night:['#9badd6','#171e2b','#232d3e','#e0e8f3']};const c=colors[settings.theme]||colors.sky;app.style.setProperty('--hy-accent',/^#[\da-f]{6}$/i.test(settings.accent)?settings.accent:c[0]);app.style.setProperty('--hy-bg',c[1]);app.style.setProperty('--hy-card',c[2]);app.style.setProperty('--hy-ink',c[3]);app.style.setProperty('--hy-radius',`${Number.isFinite(Number(settings.radius))?Math.max(0,Math.min(32,Number(settings.radius))):22}px`);app.style.fontSize=`${Number(settings.fontSize)||15}px`;
    let style=document.getElementById('hy-custom-style');if(!style){style=document.createElement('style');style.id='hy-custom-style';document.head.append(style);}style.textContent='';
    try{const sheet=new CSSStyleSheet();sheet.replaceSync(settings.customCSS||'');style.textContent=Array.from(sheet.cssRules).filter(r=>r.type===1&&!/url\s*\(|@import|expression/i.test(r.cssText)).map(r=>`${r.selectorText.split(',').map(s=>'#hy-app '+s.trim()).join(',')}{${r.style.cssText}}`).join('\n');}catch{ /* Custom CSS remains optional. */ }
}
function render(){if(!w)return;themes();const title=route.page==='artist'?'画师主页':route.page==='dm'?(route.id==='self'?'客户咨询':artistName(route.id)):route.page==='order'?'委托详情':route.page==='settings'?'设置与存档':route.page==='projects'?'企划广场':tabs.find(t=>t[0]===route.page)?.[1]||'绘约';
    const mainPage=tabs.some(t=>t[0]===route.page);
    app.innerHTML=`<header class="hy-header"><div class="hy-brand">${mainPage?'<span class="hy-flower">✿</span> 绘约':btn('back','‹ 返回')}<small>${mainPage?'让故事有了模样':E(title)}</small></div><div class="hy-header-actions"><span class="hy-day">剧情日 ${w.day}</span>${btn('advance','»','','hy-icon')}${btn('close','×','','hy-icon')}</div></header>
    <main class="hy-main" tabindex="-1">${content()}</main><nav class="hy-nav" aria-label="平台导航">${tabs.map(([id,label])=>btn('nav',`<span>${icons[id]}</span><small>${label}</small>`,id,route.page===id?'active':'')).join('')}</nav><div class="hy-modal-mount"></div>`;
    if(appearance().background){app.querySelector('.hy-main').dataset.image=appearance().background;}
    hydrate();renderChatCards();
}
function content(){switch(route.page){case 'home':return home();case 'artist':return artistPage();case 'auction':return auctions();case 'feed':return feed();case 'inbox':return inbox();case 'dm':return dm();case 'bench':return bench();case 'order':return orderPage();case 'me':return me();case 'settings':return settings();case 'projects':return projects();default:return '';}}
function home(){const list=w.artists.filter(a=>(!search||`${a.name} ${a.style} ${a.bio}`.includes(search))&&(!filter||filter==='favorite'&&a.favorite||filter==='open'&&a.open&&a.available<=w.day));return `<section class="hy-hero"><div class="hy-eyebrow">DAY ${w.day} · 绘约虚拟世界</div><h1>总有一位画师，<br>能画出你的故事。<span>✧</span></h1><p>从一个灵感开始，慢慢把喜欢变成作品。</p>${btn('projects','浏览企划 ↗','','hy-link')}</section>
    <form class="hy-search" data-form="search"><span>⌕</span><input name="q" aria-label="搜索画师" placeholder="搜索画师、画风或擅长题材" value="${E(search)}"><button>搜索</button></form>
    <div class="hy-chips">${btn('filter','推荐','',!filter?'selected':'')}${btn('filter','接稿中','open',filter==='open'?'selected':'')}${btn('filter','我的关注','favorite',filter==='favorite'?'selected':'')}</div>
    <div class="hy-section-title"><h2>发现心动画师 <small>${list.length} 位</small></h2><div>${btn('aiArtist','✧ AI 画师')}${btn('editArtist','＋ 添加')}</div></div><div class="hy-artist-grid">${list.map(a=>`<article class="hy-artist-card"><button class="hy-cover" data-act="artist" data-id="${E(a.id)}">${img(a.works[0]?.asset||a.avatar,'hy-cover-image')}<span class="hy-cover-style">${E(a.style)}</span></button><div class="hy-card-body"><div class="hy-row"><strong>${E(a.name)}</strong>${btn('favorite',a.favorite?'♥':'♡',a.id,'hy-icon')}</div><p class="hy-muted">${E(a.personality.slice(0,65))}</p><div class="hy-row"><strong class="hy-price">${money(a.min)} <small>绘币起</small></strong>${tag(a.open&&a.available<=w.day?'接稿中':'休息中')}</div>${btn('artist','查看主页 ›',a.id,'hy-full hy-soft')}</div></article>`).join('')}</div>${!list.length?empty('还没有符合条件的画师'):''}<p class="hy-footnote">所有画师、交易和绘币均属于本地虚构模拟世界。</p>`;}
function artistPage(){const a=w.artists.find(x=>x.id===route.id);if(!a)return empty('画师不存在');return `<section class="hy-profile-card"><div class="hy-profile-head">${img(a.avatar,'hy-avatar-lg')}<div><h1>${E(a.name)} ${a.linked?tag('角色已关联'):''}</h1><p>${money(a.fans)} 粉丝 · ${E(a.style)}</p></div></div><p>${E(a.bio)}</p><p class="hy-muted">${E(a.personality)}</p><div class="hy-chips">${tag(`${a.min}–${a.max} 绘币`)}${tag(`${a.days} 剧情日`)}${tag(`含 ${a.revisions} 次修改`)}${tag(`档期：第 ${a.available} 日起`)}</div><p class="hy-muted">接稿偏好：${E(a.refusal)}</p><div class="hy-actions">${btn('dm','✉ 私信画师',a.id,'hy-primary')}${btn('quote','发起委托',a.id)}${btn('favorite',a.favorite?'♥ 已关注':'♡ 关注',a.id)}</div></section>
    <div class="hy-section-title"><h2>作品橱窗</h2>${btn('addWork','＋ 上传作品',a.id)}</div><div class="hy-work-grid">${a.works.map(x=>`<article class="hy-card">${img(x.asset,'hy-work-image')}<div class="hy-card-body"><strong>${E(x.title)}</strong><div class="hy-actions">${btn('download','下载',x.asset)}${btn('removeWork','移除',x.id)}</div></div></article>`).join('')||empty('还没有作品，可以从相册上传原图')}</div>
    <section class="hy-card hy-pad"><h2>合作评价</h2>${a.reviews.map(r=>`<p>${'★'.repeat(r.stars)} ${E(r.body)} <small>第 ${r.day} 日</small></p>`).join('')||'<p class="hy-muted">暂无评价，第一段合作故事等你开启。</p>'}</section><div class="hy-actions">${btn('editArtist','编辑画师资料',a.id)}${btn('link','关联当前角色',a.id)}${a.linked?btn('unlink','解除角色关联',a.id):''}</div>`;}
function auctions(){return `<section class="hy-mini-hero"><span>♧</span><h1>把心动留给下一位。</h1><p>成稿、OC 人设与画师档期 · 仅使用虚拟绘币</p></section><div class="hy-section-title"><h2>稿拍市场</h2>${btn('createAuction','＋ 发布稿拍')}</div><div class="hy-chips">${['全部','成稿','OC 人设','画师档期','我的成交'].map(f=>btn('auctionFilter',f,f,filter===f||!filter&&f==='全部'?'selected':'')).join('')}</div><div class="hy-work-grid">${w.auctions.filter(a=>!filter||filter==='全部'||filter==='我的成交'&&a.winner===w.role||a.type===filter).map(a=>`<article class="hy-card">${a.asset?img(a.asset,'hy-work-image'):'<div class="hy-slot-art">◷<small>一段专属于你的创作档期</small></div>'}<div class="hy-card-body"><div class="hy-row"><strong>${E(a.title)}</strong>${tag(a.type)}</div><p>${E(a.description)}</p><p class="hy-muted">${a.status==='closed'?`已结束 · ${a.winner?(a.winner==='npc'?'虚拟买家':w.accounts[a.winner]?.name)+' 成交':'流拍'}`:`第 ${a.endDay} 日结束 · ${a.bids.length} 次出价`}</p><div class="hy-row"><strong class="hy-price">${money(a.bids.at(-1)?.amount||a.start)} 绘币</strong>${a.status==='open'?btn('bid','参与竞拍',a.id,'hy-primary'):a.winner===w.role&&a.asset?btn('download','下载拍品',a.asset):''}</div>${a.status==='closed'&&a.winner===w.role&&a.type==='画师档期'?btn('claimSlot','使用成交档期',a.id):''}<details><summary>出价记录</summary>${a.bids.map(b=>`<p>第 ${b.day} 日 · ${E(w.accounts[b.bidder]?.name||'虚拟买家')}：${b.amount} 绘币</p>`).join('')||'<p>暂无出价</p>'}</details></div></article>`).join('')||empty('还没有拍品，发布一件作品或档期吧')}</div>`;}
function feed(){return `<div class="hy-section-title"><div><div class="hy-eyebrow">OUR LITTLE STORIES</div><h1>创作之外，也有生活。</h1></div>${btn('createPost','＋ 发布','','hy-primary')}</div><div class="hy-chips">${['全部','稿件','生活','灵感','公告'].map(f=>btn('feedFilter',f,f,feedFilter===f?'selected':'')).join('')}</div>${w.posts.filter(p=>feedFilter==='全部'||p.category===feedFilter).map(p=>`<article class="hy-card hy-post"><div class="hy-row"><div class="hy-author">${img(p.avatar||w.artists.find(a=>a.id===p.artistId)?.avatar,'hy-avatar')}<div><strong>${E(p.author)}</strong><small>第 ${p.day} 日 · ${E(p.category)}</small></div></div>${tag(p.artistId?'画师动态':p.role==='artist'?'画师':'委托人')}</div><p class="hy-pre">${E(p.body)}</p>${p.asset?img(p.asset,'hy-post-image'):''}<div class="hy-actions">${btn('like',`${p.liked?'♥':'♡'} ${p.likes}`,p.id)}${btn('comment',`评论 ${p.comments.length}`,p.id)}</div>${p.comments.map(c=>`<div class="hy-comment"><strong>${E(c.author)}</strong> ${E(c.body)}</div>`).join('')}</article>`).join('')||empty('广场还很安静，发布第一条动态吧',btn('aiPost','✧ 生成一条画师动态'))}<div class="hy-actions">${btn('aiPost','✧ AI 画师动态')}${btn('npcPost','生成模拟动态')}</div>`;}
function inbox(){const msgs=Object.entries(w.messages).filter(([key])=>key.startsWith(w.role+':'));return `<div class="hy-section-title"><h1>消息</h1>${tag(w.role==='client'?'甲方收件箱':'画师收件箱')}</div>${msgs.map(([key,ms])=>{const id=key.split(':')[1],a=w.artists.find(a=>a.id===id);return `<button class="hy-thread" data-act="dm" data-id="${E(id)}">${img(a?.avatar||w.accounts.artist.avatar,'hy-avatar')}<div><strong>${E(artistName(id))}</strong><p>${E(ms.at(-1)?.body.slice(0,80))}</p></div><span>›</span></button>`;}).join('')||empty('还没有私信，去橱窗找一位喜欢的画师吧')}<h2>平台通知</h2>${w.notifications.filter(n=>n.role==='all'||n.role===w.role).slice(0,30).map(n=>`<article class="hy-card hy-pad"><small>剧情日 ${n.day}</small><p>${E(n.message)}</p></article>`).join('')||'<p class="hy-muted">暂无通知</p>'}`;}
function versionCard(o,v){const busy=running.has(v.id),label=busy?(v.status==='drawing'?'绘制中…':'生成中…'):v.asset?'查看稿件 / 下载':v.status==='failed'?'重试当前步骤':v.positive?'生成图片':'生成提示词';return `<div class="hy-art-bubble" data-version="${E(v.id)}"><div class="hy-row"><strong>${E(v.stage)} V${v.number}</strong>${tag(v.source==='upload'?'手动上传':v.source==='ai'?'AI 生成':'稿件占位')}</div><div class="hy-art-content"><button type="button" class="hy-art-preview" data-act="view" data-id="${E(v.id)}">${v.asset?img(v.asset,'hy-art-image'):'<span>▧</span><small>等待添加稿件</small>'}</button><div class="hy-art-tools">${btn('versionMain',label,v.id,'hy-primary')}${btn('uploadVersion','↑ 上传图片',v.id)}${btn('editPrompt','☷ 提示词',v.id)}${busy?btn('cancelTask','放弃本次结果',v.id):''}</div></div><p class="hy-muted">${E(v.note||'尚未填写稿件说明')}</p>${v.error?`<p class="hy-error">${E(v.error)}</p>`:''}<small>第 ${v.day} 日${v.accepted?' · 已验收':''}</small></div>`;}
function dm(){const id=route.id,a=w.artists.find(a=>a.id===id),ms=w.messages[`${w.role}:${id}`]||[];return `<div class="hy-dm-head">${img(a?.avatar||w.accounts.artist.avatar,'hy-avatar')}<div><strong>${E(id==='self'?'客户咨询':artistName(id))}</strong><small>${id==='self'?'虚拟客户私信':'独立角色上下文 · '+(a?.open?'模拟在线':'暂时离线')}</small></div>${id!=='self'?btn('quote','约稿',id):btn('incoming','新客户')}</div><div class="hy-chat" id="hy-dm-log">${ms.map(m=>{let art='';if(m.versionId){try{const {o,v}=C.findVersion(w,m.versionId);art=versionCard(o,v);}catch{}}return `<div class="hy-message ${m.from==='user'?'self':''}"><small>${m.from==='user'?E(profile().name):m.from==='client'?'虚拟客户':E(artistName(id))} · 第 ${m.day} 日</small><div class="hy-message-text hy-pre">${E(m.body)}</div>${art}</div>`;}).join('')||empty('从打个招呼开始吧。你们的故事会保存在这里。')}</div><form class="hy-composer" data-form="dm"><textarea name="body" rows="2" maxlength="10000" required placeholder="聊聊 OC、构图、修改想法…" aria-label="私信内容"></textarea><button class="hy-primary" ${running.has('dm:'+id)?'disabled':''}>${running.has('dm:'+id)?'回复中…':'发送 ↗'}</button></form><div class="hy-actions">${btn('retryDM','重新请求回复',id)}${btn('manualReply','手动扮演对方',id)}${btn('makePlaceholder','添加稿件占位',id)}</div><p class="hy-footnote">AI 报价仅供沟通参考。订单金额以「发起委托」确认的数值为准。</p>`;}
function bench(){const os=w.commissions.filter(o=>o.owner===w.role&&(!filter||o.status===filter));return `<div class="hy-section-title"><h1>每个灵感，都在慢慢成形。</h1>${w.role==='artist'?btn('incoming','＋ 模拟客户'):''}</div><div class="hy-chips">${[['','全部'],['quoted','待确认'],['working','绘制中'],['review','待验收'],['complete','已完成']].map(([id,l])=>btn('filter',l,id,filter===id?'selected':'')).join('')}</div>${os.map(o=>`<article class="hy-card hy-pad"><div class="hy-row"><strong>${E(o.title)}</strong>${tag(status[o.status])}</div><p class="hy-muted">${E(artistName(o.artistId))} · ${o.price} 绘币${o.dueDay?` · 约定第 ${o.dueDay} 日交付`:''}</p><div class="hy-progress">${C.STAGES.map((s,i)=>`<span class="${o.stage>=i?'done':''}">${s}</span>`).join('')}</div><div class="hy-row"><small>${o.versions.length} 个版本 · 已修改 ${o.revisions}/${o.maxRevisions} 次</small>${btn('order','打开工作板 ›',o.id,'hy-soft')}</div></article>`).join('')||empty('这里会记录你的每一次约稿和交付')}`;}
function orderPage(){let o;try{o=getOrder(route.id);}catch{return empty('订单不存在');}return `<section class="hy-card hy-pad"><div class="hy-row"><h1>${E(o.title)}</h1>${tag(status[o.status])}</div><p>${E(o.brief)}</p><p class="hy-muted">${E(artistName(o.artistId))} · ${o.price} 绘币 · ${o.days} 剧情日 · ${o.commercial?'商用需求':'个人用途'}</p><div class="hy-progress">${C.STAGES.map((s,i)=>`<span class="${o.stage>=i?'done':''}">${s}</span>`).join('')}</div><p>当前阶段：${C.STAGES[o.stage]} · 修改次数 ${o.revisions}/${o.maxRevisions}</p><div class="hy-actions">${o.status==='quoted'?(o.owner==='client'?btn('pay','确认并托管付款',o.id,'hy-primary'):btn('acceptIncoming','接受客户委托',o.id,'hy-primary')):''}${o.status==='working'?btn('placeholder','提交阶段稿件占位',o.id,'hy-primary'):''}${o.status==='review'?btn('approve',o.owner==='artist'?'模拟客户验收':'确认本阶段验收',o.id,'hy-primary')+btn('revise',o.owner==='artist'?'模拟客户提出修改':'提出修改',o.id):''}${!['complete','cancelled'].includes(o.status)?btn('cancelOrder','协商取消',o.id):''}${btn('dm','打开私信',o.artistId)}${btn('orderAutomation','本订单自动化',o.id)}${o.status==='complete'&&!o.reviewed&&o.owner==='client'?btn('review','评价画师',o.id):''}</div></section><div class="hy-section-title"><h2>稿件版本库</h2>${btn('exportOrder','导出订单稿件包',o.id)}</div>${o.versions.map(v=>`<article class="hy-card hy-pad">${versionCard(o,v)}<div class="hy-actions">${btn('newVersion','从此版新建修改版',v.id)}${btn('editNote','编辑文字稿说明',v.id)}${v.asset?btn('download','下载原图',v.asset):''}</div></article>`).join('')||empty('等待画师提交第一版稿件')}`;}
function me(){const p=profile();return `<section class="hy-profile-card"><div class="hy-profile-head">${img(p.avatar,'hy-avatar-lg')}<div><div class="hy-eyebrow">${w.role==='client'?'COMMISSIONER':'ARTIST'}</div><h1>${E(p.name)}</h1><small>ID ${E(p.id.slice(0,8))}</small></div></div><p>${E(p.bio)}</p><div class="hy-row"><div><small>可用绘币</small><div class="hy-wallet">${money(p.balance)} <small>✧</small></div></div>${btn('switchRole',w.role==='client'?'✎ 切换画师身份':'♡ 切换甲方身份','','hy-soft')}</div><div class="hy-actions">${btn('editAccount','编辑个人资料')}${btn('wallet','钱包记录')}</div></section><div class="hy-settings-menu">${btn('settings','⚙ 设置、AI 接口与存档 ›')}${btn('bridge','⇄ 角色关联与剧情同步 ›')}${btn('npc','✧ 提取角色卡 / 世界书中的 NPC ›')}${btn('accountStyle','❀ 主题与界面美化 ›')}${btn('bench','▣ 我的稿件与订单 ›')}</div><section class="hy-card hy-pad"><h2>身份说明</h2><p class="hy-muted">甲方和画师拥有独立资料、钱包与消息。切换平台身份不会切换酒馆当前角色。画师身份首次启用后，才会开始接收模拟客户消息。</p></section>`;}
function apiFields(kind,label){const s=w.settings[kind];return `<fieldset><legend>${label}</legend><label>调用方式<select name="${kind}.mode"><option value="tavern" ${s.mode==='tavern'?'selected':''}>使用酒馆当前${kind==='image'?'图片扩展':'对话模型'}</option><option value="openai" ${s.mode==='openai'?'selected':''}>独立 OpenAI 兼容接口</option>${kind==='image'?A.imageAdapters().map(a=>`<option value="${E(a.id)}" ${s.mode===a.id?'selected':''}>${E(a.label)}</option>`).join(''):''}</select></label><label>API 根地址（含 /v1，不含具体接口）<input name="${kind}.url" value="${E(s.url)}" placeholder="https://example.com/v1"></label><label>模型名<input name="${kind}.model" value="${E(s.model)}"></label><label>API Key（仅内存保存，不写入存档）<input type="password" autocomplete="off" name="${kind}.key" placeholder="${A.hasKey(kind)?'已设置；留空保留':'可选，按服务要求填写'}"></label>${kind!=='image'?`<label>独立提示词模板<textarea name="${kind}.template" rows="4">${E(s.template)}</textarea></label>`:''}</fieldset>`;}
function settings(){return `<h1>让绘约，成为你的样子。</h1><form data-form="settings" class="hy-form"><fieldset><legend>自动化与剧情</legend>${check('autoPrompt','稿件占位后自动生成提示词',w.settings.autoPrompt)}${check('autoImage','有提示词后自动生成图片',w.settings.autoImage)}${check('randomEvents','启用剧情随机事件、NPC 竞价与生活动态',w.settings.randomEvents)}${check('sharedProfile','两种身份共用昵称、简介、头像和美化',w.settings.sharedProfile)}<p class="hy-muted">自动开关仅影响之后新建的稿件。打开页面、刷新、读取聊天不会自动补发 API 请求。手动上传始终可用。</p></fieldset>${apiFields('chat','AI 私信与人物生成')}${apiFields('prompt','独立提示词 AI')}${apiFields('image','绘图服务')}<fieldset><legend>绘图参数</legend>${field('width','宽度',w.settings.image.width,'number')}${field('height','高度',w.settings.image.height,'number')}${field('steps','Steps',w.settings.image.steps,'number')}${field('cfg','CFG',w.settings.image.cfg,'number')}<p class="hy-muted">酒馆模式复用图片扩展选择的服务，可使用其支持的 NovelAI、SD、ComfyUI 等。独立模式支持 /images/generations；各服务的尺寸、参考图与重绘能力不同。修改版本保留提示词和种子，但通用文生图不保证构图一致。</p></fieldset><button class="hy-primary">保存设置</button></form><section class="hy-card hy-pad"><h2>完整存档</h2><p class="hy-muted">存档包含本世界的所有资料、订单、稿件原文件和头像。可在电脑与手机间手动迁移。浏览器数据不会自动同步到其他设备，请定期导出。</p><div class="hy-actions">${btn('export','导出完整存档')}${btn('import','恢复完整存档')}${btn('reset','重置当前世界')}</div></section><p class="hy-footnote">独立 API 由浏览器直接请求，需要服务允许跨域访问。密钥只保留至页面关闭；不要将密钥写在地址或模板中。</p>`;}
function projects(){return `<div class="hy-section-title"><h1>把灵感写成企划。</h1>${btn('createProject','＋ 发布企划')}</div>${w.projects.map(p=>`<article class="hy-card hy-pad"><div class="hy-row"><strong>${E(p.title)}</strong>${tag(`${p.budget} 绘币预算`)}</div><p>${E(p.brief)}</p><p class="hy-muted">第 ${p.deadline} 日截稿 · ${p.applicants.length} 位画师应征</p><div class="hy-actions">${btn('applicants','邀请 / 查看应征',p.id)}${btn('simulateApplicants','征集虚拟应征',p.id)}</div></article>`).join('')||empty('可以先写下想要的画面，再寻找合适的画师')}`;}
const field=(name,label,value='',type='text',extra='')=>`<label>${E(label)}<input type="${type}" name="${name}" value="${E(value)}" ${extra}></label>`;
const area=(name,label,value='',rows=4)=>`<label>${E(label)}<textarea name="${name}" rows="${rows}">${E(value)}</textarea></label>`;
const check=(name,label,on)=>`<label class="hy-toggle"><input type="checkbox" name="${name}" ${on?'checked':''}><span>${E(label)}</span></label>`;
function closeModal(){modalCleanup?.();modalCleanup=null;app.querySelector('.hy-modal-mount')?.replaceChildren();}
function modal(title,body,onSubmit,label='保存'){closeModal();const mount=app.querySelector('.hy-modal-mount');mount.innerHTML=`<div class="hy-modal-backdrop"><section class="hy-modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="hy-row"><h2>${E(title)}</h2>${btn('closeModal','×','','hy-icon')}</div><form class="hy-form">${body}${onSubmit?`<button class="hy-primary" type="submit">${E(label)}</button>`:''}</form></section></div>`;
    const form=mount.querySelector('form');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');if(button?.disabled)return;if(button)button.disabled=true;try{await onSubmit?.(new FormData(form),form);closeModal();await persist();render();}catch(e){toast(e.message,true);if(button)button.disabled=false;}});
    const key=e=>{if(e.key==='Escape'){e.stopPropagation();closeModal();}if(e.key==='Tab'){const els=[...mount.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};mount.addEventListener('keydown',key);modalCleanup=()=>mount.removeEventListener('keydown',key);setTimeout(()=>mount.querySelector('input,textarea,button')?.focus(),20);
}
function confirmModal(title,body,callback){modal(title,`<p>${E(body)}</p>`,callback,'确认');}
async function pickFile(accept){return new Promise(resolve=>{const i=document.createElement('input');i.type='file';i.accept=accept;i.style.display='none';document.body.append(i);let done=false;const finish=f=>{if(done)return;done=true;i.remove();resolve(f);};i.addEventListener('change',()=>finish(i.files?.[0]));i.addEventListener('cancel',()=>finish());i.click();});}
async function upload(){const f=await pickFile('image/png,image/jpeg,image/webp,image/gif,image/avif,image/bmp');return f?S.putAsset(f,f.name):null;}
function artistForm(id){const a=w.artists.find(x=>x.id===id)||C.artist();modal(id?'编辑画师':'添加自己的画师',`${field('name','昵称',a.name)}${area('bio','个人简介',a.bio)}${area('personality','人设、性格和沟通习惯',a.personality)}${field('style','画风 / 擅长题材',a.style)}${field('fans','粉丝数',a.fans,'number')}${field('min','最低报价',a.min,'number')}${field('max','最高报价',a.max,'number')}${field('days','约稿工期（剧情日）',a.days,'number')}${field('available','开始接稿的剧情日',a.available,'number')}${field('revisions','包含修改次数',a.revisions,'number')}${area('refusal','接稿限制与偏好',a.refusal,2)}${check('open','开放接稿',a.open)}<label>头像（从手机相册或文件选择）<input type="file" name="avatarFile" accept="image/*"></label>`,async f=>{const min=C.integer(f.get('min'),1),max=C.integer(f.get('max'),min);const v={name:C.text(f.get('name'),50),bio:C.text(f.get('bio'),4000),personality:C.text(f.get('personality'),2000),style:C.text(f.get('style'),500),fans:C.integer(f.get('fans')),min,max,days:C.integer(f.get('days'),1,365),available:C.integer(f.get('available'),1),revisions:C.integer(f.get('revisions'),0,30),refusal:C.text(f.get('refusal'),1000),open:f.has('open')};if(!v.name)throw Error('请输入昵称');const file=f.get('avatarFile');if(file?.size)v.avatar=await putAssetSafe(file,file.name);if(id)Object.assign(a,v);else w.artists.push({...a,...v});});}
function quoteForm(id,preset={}){const a=w.artists.find(a=>a.id===id);if(!a)throw Error('请先选一位画师');if(w.role!=='client')throw Error('请先切换甲方身份');modal(`向 ${a.name} 发起委托`,`${field('title','委托标题',preset.title||'我的 OC 插画')}${area('brief','人设、服装、构图与细节需求',preset.brief||'')}${field('price',`协商报价（${a.min}–${a.max} 绘币）`,preset.budget?Math.min(a.max,Math.max(a.min,preset.budget)):a.min,'number')}${field('days','约定工期（剧情日）',a.days,'number')}${check('commercial','需要商用授权（请在需求中说明范围）',false)}<p class="hy-muted">创建后仍需确认付款。画师接稿状态和档期由系统检查。AI 聊天中的金额不会自动扣款。</p>`,f=>{const o=C.quote(w,id,{title:f.get('title'),brief:f.get('brief'),price:f.get('price'),days:f.get('days'),commercial:f.has('commercial')});route={page:'order',id:o.id};},'创建待确认订单');}
function automation(o,key){return typeof o.automation?.[key]==='boolean'?o.automation[key]:w.settings[key];}
function afterPlaceholder(v){const {o}=C.findVersion(w,v.id);if(automation(o,'autoPrompt'))startTask(v.id,'prompt');else if(automation(o,'autoImage')&&v.positive)startTask(v.id,'image');}
function taskValid(token){return token.epoch===epoch&&!token.controller.signal.aborted&&running.get(token.id)===token;}
function startTask(id,kind){
    if(running.has(id))return;const {o,v}=C.findVersion(w,id);if(kind==='image'&&!v.positive)throw Error('请先填写或生成提示词');if(v.asset)throw Error('当前版本已有原图，请先新建修改版，旧稿不会被覆盖');
    if([...running.values()].some(t=>t.kind!=='dm'))throw Error('已有生成任务，请等待或放弃当前结果后再试');
    const token={id,kind,epoch,controller:new AbortController()};running.set(id,token);v.status=kind==='prompt'?'prompting':'drawing';v.error=null;persist().catch(e=>toast(e.message,true));render();
    const captured=structuredClone({o,v,settings:w.settings,artist:w.artists.find(a=>a.id===o.artistId)});
    (async()=>{
        try{
            if(kind==='prompt'){
                const previous=captured.o.versions.filter(x=>x.id!==id).at(-1);
                const raw=await completeSafe(captured.settings.prompt,'prompt',[{role:'user',content:JSON.stringify({brief:captured.o.brief,style:captured.artist?.style,stage:captured.v.stage,revision:captured.o.lastRevision,note:captured.v.note,previous:previous?{positive:previous.positive,negative:previous.negative,seed:previous.seed}:null})}],token.controller.signal);
                if(!taskValid(token))return;const p=A.parseJSON(raw);if(typeof p.positive!=='string'||!p.positive.trim())throw Error('AI 没有返回 positive 提示词');v.positive=C.text(p.positive);v.negative=C.text(p.negative);v.status='prompted';v.source='ai';
            }else{
                const result=await A.draw(captured.settings.image,captured.v,token.controller.signal);if(!taskValid(token))return;v.asset=result.asset;v.params=result.params;v.source='ai';v.status='ready';
            }
            await persist();toast(kind==='prompt'?'提示词已生成，可编辑后再出图':'图片已保存至版本库');
        }catch(e){if(taskValid(token)){v.status='failed';v.error=e.message;await persist().catch(()=>{});toast(e.message,true);}}
        finally{if(running.get(id)===token){running.delete(id);if(token.epoch===epoch){render();if(kind==='prompt'&&v.status==='prompted'&&automation(o,'autoImage'))startTask(id,'image');}}}
    })();
}
async function aiReply(id){
    const key='dm:'+id;if(running.has(key))return;const a=w.artists.find(a=>a.id===id);const role=w.role;if(!a&&id!=='self')throw Error('画师不存在');
    if(!a?.open&&id!=='self'){C.message(w,id,role,'你好，收到消息啦。我目前暂不接稿，可以先把需求留下。',{from:'artist'});await persist();render();return;}
    const token={id:key,kind:'dm',epoch,controller:new AbortController()};running.set(key,token);render();
    const ms=(w.messages[`${role}:${id}`]||[]).filter(m=>!m.versionId).slice(-18).map(m=>({role:m.from==='user'?'user':'assistant',content:m.body}));
    const info={name:a?.name||'虚拟约稿客户',bio:a?.bio,personality:a?.linked?.personality||a?.personality,originalRole:a?.linked,style:a?.style,range:a?[a.min,a.max]:null,refusal:a?.refusal,day:w.day,orders:w.commissions.filter(o=>o.artistId===id&&o.owner===role).slice(-4).map(o=>({title:o.title,brief:o.brief,status:o.status,stage:C.STAGES[o.stage],price:o.price,lastRevision:o.lastRevision}))};
    try{const raw=await completeSafe(w.settings.chat,'chat',[{role:'system',content:`当前私信对方资料与权威订单状态：${JSON.stringify(info)}。只扮演这个人物；不要声称已扣款或修改系统状态。图片尚未生成时可以提议提交占位。`},...ms],token.controller.signal);if(taskValid(token)){C.message(w,id,role,raw,{from:id==='self'?'client':'artist'});await persist();}}
    catch(e){if(taskValid(token))toast(`私信失败，已保留发送内容：${e.message}`,true);}finally{if(running.get(key)===token){running.delete(key);if(epoch===token.epoch)render();}}
}
async function newModification(id){const {o,v}=C.findVersion(w,id);if(!['working','review'].includes(o.status))throw Error('已结束订单不能新建修改稿');const n={...structuredClone(v),id:C.uid(),number:o.versions.length+1,day:w.day,asset:null,accepted:false,status:v.positive?'prompted':'empty',source:'placeholder',error:null,parentId:v.id};o.versions.push(n);o.status='review';C.message(w,o.artistId,o.owner,`新建${n.stage} V${n.number}，保留上一版提示词与种子供修改。`,{from:'artist',orderId:o.id,versionId:n.id});await persist();}
function bridgeModal(){const ch=B.currentCharacter();modal('角色关联与剧情同步',`<p>当前角色：${E(ch?.name||'未打开聊天')}</p><p class="hy-muted">当前世界独立存档；开启「绑定当前聊天」后，为这个聊天创建或恢复独立世界，不会替换角色卡。角色关联请进入画师主页。</p><div class="hy-actions">${btn('bindChat','绑定 / 打开当前聊天世界')}${btn('globalWorld','打开独立世界')}</div><fieldset><legend>聊天双向联动（当前世界）</legend>${check('bridgeEnabled','监听已关联角色的交稿话语，建立待确认事件',w.settings.bridgeEnabled)}${check('inject','将最近平台状态作为简短提示注入酒馆对话',w.settings.inject)}</fieldset><h3>同步日志与待确认事件</h3>${w.bridge.map(e=>`<article class="hy-card hy-pad"><small>第 ${e.day} 日 · ${E(e.status)}</small><p>${E(e.body)}</p>${e.status==='pending'?btn('applyBridge','选择订单并确认',e.id)+btn('dismissBridge','忽略',e.id):e.status==='applied'?btn('undoBridge','撤销此同步',e.id):''}</article>`).join('')||'<p class="hy-muted">暂无同步事件</p>'}<h3>平台事件摘要</h3>${w.events.slice(-15).reverse().map(e=>`<p class="hy-muted">第 ${e.day} 日 · ${E(e.message)}</p>`).join('')}`,f=>{w.settings.bridgeEnabled=f.has('bridgeEnabled');w.settings.inject=f.has('inject');});}
function styleModal(){const style=appearance();modal('主题与界面美化',`<label>主题<select name="theme">${[['sky','晴空蓝'],['rose','山茶粉'],['mint','薄荷绿'],['night','夜间创作']].map(([v,s])=>`<option value="${v}" ${style.theme===v?'selected':''}>${s}</option>`).join('')}</select></label>${field('accent','主色',style.accent,'color')}${field('radius','卡片圆角（0–32）',style.radius,'number')}${field('fontSize','字体大小（12–22）',style.fontSize,'number')}<label>背景图<input type="file" name="background" accept="image/*"></label>${check('removeBackground','移除背景图',false)}${area('css','自定义 CSS（仅普通选择器，自动限定在绘约内部）',style.customCSS,6)}<p class="hy-muted">例：.hy-card { border-width: 2px; }。不支持 @import、媒体规则及 CSS 外部图片地址。</p>`,async f=>{style.theme=f.get('theme');style.accent=f.get('accent');style.radius=C.integer(f.get('radius'),0,32);style.fontSize=C.integer(f.get('fontSize'),12,22);style.customCSS=C.text(f.get('css'),20000);if(f.has('removeBackground'))style.background=null;const file=f.get('background');if(file?.size)style.background=await putAssetSafe(file,file.name);const values=Object.fromEntries(['theme','accent','radius','fontSize','background','customCSS'].map(k=>[k,style[k]]));if(w.settings.sharedProfile)Object.assign(w.settings,values);else profile().appearance=values;});}
const actions={
    orderAutomation:id=>{const o=getOrder(id);modal('本订单的自动生成设置',`<p class="hy-muted">可以单独覆盖全局开关；只对之后的占位和执行链生效。</p>${['autoPrompt','autoImage'].map((k,i)=>`<label>${i?'图片生成':'提示词生成'}<select name="${k}"><option value="inherit" ${typeof o.automation?.[k]!=='boolean'?'selected':''}>跟随全局设置</option><option value="on" ${o.automation?.[k]===true?'selected':''}>自动生成</option><option value="off" ${o.automation?.[k]===false?'selected':''}>手动触发</option></select></label>`).join('')}`,f=>{o.automation={};for(const k of ['autoPrompt','autoImage'])if(f.get(k)!=='inherit')o.automation[k]=f.get(k)==='on';});},
    close:()=>{app.hidden=true;opened=false;launcher.hidden=false;},closeModal,
    nav:id=>go(id),back:()=>go(['artist','projects'].includes(route.page)?'home':['dm','order'].includes(route.page)?route.page==='dm'?'inbox':'bench':'me'),
    artist:id=>go('artist',id),dm:id=>{go('dm',id);setTimeout(()=>app.querySelector('#hy-dm-log')?.lastElementChild?.scrollIntoView({block:'end'}),30);},order:id=>go('order',id),bench:()=>go('bench'),settings:()=>go('settings'),projects:()=>go('projects'),
    filter:id=>{filter=id;render();},auctionFilter:id=>{filter=id;render();},feedFilter:id=>{feedFilter=id;render();},
    favorite:id=>{const a=w.artists.find(a=>a.id===id);a.favorite=!a.favorite;render();},editArtist:artistForm,
    aiArtist:()=>modal('AI 创建画师',area('idea','描述想要的画师','想要一位擅长梦幻水彩、慢热温柔的画师。'),async f=>{
        const raw=await completeSafe(w.settings.chat,'chat',[{role:'user',content:`创建一位全新的虚拟画师，不改写已有画师。只输出 JSON 对象：name,bio,personality,style,fans(整数),min(1-100000整数),max(>=min),days(1-365整数),revisions(0-30整数),refusal。需求：${C.text(f.get('idea'))}`}]);const p=A.parseJSON(raw);const a=C.artist({name:C.text(p.name,50)||'新画师',bio:C.text(p.bio,4000),personality:C.text(p.personality,2000),style:C.text(p.style,500),fans:C.integer(p.fans??0),min:C.integer(p.min??280,1),max:C.integer(p.max??1200,1),days:C.integer(p.days??12,1,365),revisions:C.integer(p.revisions??2,0,30),refusal:C.text(p.refusal,1000)});if(a.max<a.min)throw Error('AI 报价范围有误，请重试');w.artists.push(a);C.notify(w,`新画师 ${a.name} 加入绘约`);
    },'生成并添加'),
    quote:quoteForm,
    addWork:id=>modal('上传作品',`${field('title','作品标题','新的作品')}<label>原图<input type="file" accept="image/*" name="file" required></label>`,async f=>{const a=w.artists.find(a=>a.id===id),file=f.get('file');const asset=await putAssetSafe(file,file.name);a.works.push({id:C.uid(),title:C.text(f.get('title'),100),asset});}),
    removeWork:id=>confirmModal('移除作品','将从画师主页移除这张作品。订单版本与其他原文件不受影响。',()=>{for(const a of w.artists)a.works=a.works.filter(x=>x.id!==id);}),
    download:id=>S.downloadAsset(id),
    link:id=>confirmModal('关联当前角色',`将「${B.currentCharacter()?.name||'未打开角色'}」的身份资料关联到此画师，原角色卡不被修改。`,()=>B.linkCurrent(w.artists.find(a=>a.id===id))),
    unlink:id=>{w.artists.find(a=>a.id===id).linked=null;render();},
    pay:id=>confirmModal('确认订单并付款',`将 ${getOrder(id).price} 绘币转入虚拟托管。订单会按剧情天数推进，每阶段等待你验收。`,()=>{C.pay(w,id);}),
    acceptIncoming:id=>C.acceptIncoming(w,id),
    placeholder:id=>{const v=C.placeholder(w,id);persist().then(()=>afterPlaceholder(v)).catch(e=>toast(e.message,true));render();},
    makePlaceholder:id=>{const orders=w.commissions.filter(o=>o.owner===w.role&&o.artistId===id&&['working','review'].includes(o.status));if(!orders.length)throw Error('请先创建并确认一份委托订单');modal('选择稿件对应的订单',`<label>订单<select name="order">${orders.map(o=>`<option value="${E(o.id)}">${E(o.title)} · ${C.STAGES[o.stage]}</option>`).join('')}</select></label>`,f=>{const v=C.placeholder(w,f.get('order'));setTimeout(()=>afterPlaceholder(v),50);});},
    approve:id=>confirmModal('确认阶段验收',`确认「${getOrder(id).title}」的${C.STAGES[getOrder(id).stage]}阶段。文字稿也可以验收；图片生成需要另外操作。`,()=>C.approve(w,id)),
    revise:id=>modal('提出修改意见',area('note','请具体描述希望修改的细节'),f=>C.revise(w,id,f.get('note'))),
    cancelOrder:id=>confirmModal('协商取消委托','模拟双方已同意取消。已托管的甲方绘币会全额退回，稿件版本将保留。',()=>C.cancelOrder(w,id)),
    review:id=>modal('评价画师',`<label>星级<select name="stars">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select></label>${area('body','合作感受')}`,f=>{const o=getOrder(id);if(o.status!=='complete'||o.reviewed)throw Error('订单尚未完成或已经评价');const a=w.artists.find(a=>a.id===o.artistId);a.reviews.push({stars:C.integer(f.get('stars'),1,5),body:C.text(f.get('body'),2000),day:w.day});o.reviewed=true;}),
    versionMain:id=>{const {v}=C.findVersion(w,id);if(running.has(id))return;if(v.asset)return actions.view(id);startTask(id,v.positive?'image':'prompt');},
    view:id=>{const {v}=C.findVersion(w,id);modal(`${v.stage} V${v.number}`,`${v.asset?img(v.asset,'hy-full-image'):empty('图片尚未添加')}${v.asset?btn('download','↓ 下载原文件',v.asset):''}<p>${E(v.note)}</p><details><summary>生成参数与提示词</summary><pre>${E(JSON.stringify({positive:v.positive,negative:v.negative,seed:v.seed,params:v.params},null,2))}</pre></details>`);hydrate();},
    cancelTask:id=>{const t=running.get(id);if(t){t.controller.abort();running.delete(id);}const {v}=C.findVersion(w,id);v.status=v.asset?'ready':v.positive?'prompted':'empty';v.error=null;toast('已放弃本次返回结果。酒馆或远端 API 可能仍在执行和计费。');render();},
    uploadVersion:async id=>{const {o,v}=C.findVersion(w,id);const capturedEpoch=epoch,asset=await upload();if(!asset||capturedEpoch!==epoch)return;running.get(id)?.controller.abort();running.delete(id);if(v.asset){const n={...structuredClone(v),id:C.uid(),parentId:v.id,number:o.versions.length+1,asset,source:'upload',status:'ready',accepted:false,error:null,day:w.day};o.versions.push(n);C.message(w,o.artistId,o.owner,`上传了一份新的 ${n.stage} V${n.number}，旧版本已经保留。`,{from:'artist',orderId:o.id,versionId:n.id});}else{v.asset=asset;v.status='ready';v.source='upload';v.error=null;}render();},
    newVersion:newModification,
    editPrompt:id=>{const {o,v}=C.findVersion(w,id);const promptEpoch=epoch;if(running.has(id))throw Error('请先放弃正在生成的结果');modal('编辑本版提示词',`${area('positive','正向提示词',v.positive,6)}${area('negative','负向提示词',v.negative,3)}${field('seed','种子（保留以供复现）',v.seed,'number')}<p class="hy-muted">${v.asset?'此版本已有原图，修改提示词需要创建新版本。':'保存后点击「生成图片」执行下一步。'}</p>`,async f=>{let target=v;if(v.asset||v.accepted){await newModification(id);target=C.findVersion(w,id).o.versions.at(-1);}target.positive=C.text(f.get('positive'));target.negative=C.text(f.get('negative'));target.seed=C.integer(f.get('seed'),0,2147483647);target.status=target.positive?'prompted':'empty';target.error=null;if(target.positive&&automation(o,'autoImage'))setTimeout(()=>{if(promptEpoch===epoch)try{startTask(target.id,'image');}catch(e){toast(e.message,true);}},80);});},
    editNote:id=>{const {v}=C.findVersion(w,id);modal('文字稿件说明',area('note','构图、配色、阶段成果或修改说明',v.note,6),f=>{v.note=C.text(f.get('note'));});},
    advance:()=>modal('推进剧情时间',`<p>目前是剧情日 ${w.day}。只有主动推进才会改变工期和拍卖日期。</p><label>推进天数<select name="days"><option value="1">1 天</option><option value="3">3 天</option><option value="7">1 周</option></select></label><p class="hy-muted">待验收的稿件会暂停推进，不会跳过阶段。随机事件可在设置中关闭。</p>`,f=>{const vs=C.advance(w,f.get('days'));setTimeout(()=>{if(vs.length)autoQueue(vs.map(v=>v.id));},100);},'推进'),
    createAuction:()=>modal('发布稿拍',`${field('title','拍品名称')}<label>类型<select name="type"><option>成稿</option><option>OC 人设</option><option>画师档期</option></select></label>${area('description','介绍、授权与档期说明')}${field('start','起拍价',100,'number')}${field('increment','最小加价',20,'number')}${field('duration','持续剧情天数',3,'number')}<label>拍品图片（档期类型可不传）<input type="file" name="file" accept="image/*"></label>`,async f=>{let asset=null;const file=f.get('file');if(file?.size)asset=await putAssetSafe(file,file.name);C.auction(w,{...Object.fromEntries(f),asset,seller:w.role});}),
    bid:id=>{const a=w.auctions.find(x=>x.id===id),min=a.bids.at(-1)?a.bids.at(-1).amount+a.increment:a.start;modal('参与虚拟竞拍',`<p>出价后会预留绘币，被超价时立即退回。剧情日 ${a.endDay} 结束时自动结算。</p>${field('amount','你的出价',min,'number')}`,f=>C.bid(w,id,f.get('amount'),w.role),'确认出价');},
    claimSlot:id=>{const a=w.auctions.find(a=>a.id===id);if(a.winner!==w.role||a.type!=='画师档期')throw Error('没有这个档期的使用权');modal('使用成交档期',`<p>档期所有权已经保存。请指定关联画师后发起委托，画费另行协商；成交金额视为购买档期费用。</p><label>画师<select name="artistId">${w.artists.map(a=>`<option value="${E(a.id)}">${E(a.name)}</option>`).join('')}</select></label>`,f=>{a.artistId=f.get('artistId');const ar=w.artists.find(x=>x.id===a.artistId);ar.available=w.day;ar.open=true;route={page:'artist',id:ar.id};});},
    createPost:()=>modal('发布一条动态',`<label>分类<select name="category"><option>稿件</option><option>生活</option><option>灵感</option><option>公告</option></select></label>${area('body','想分享什么？')}<label>图片<input type="file" name="file" accept="image/*"></label>`,async f=>{const body=C.text(f.get('body'));if(!body)throw Error('请填写动态正文');let asset=null;const file=f.get('file');if(file?.size)asset=await putAssetSafe(file,file.name);w.posts.unshift({id:C.uid(),author:profile().name,avatar:profile().avatar,role:w.role,body,category:f.get('category'),asset,day:w.day,likes:0,liked:false,comments:[]});}),
    like:id=>{const p=w.posts.find(p=>p.id===id);p.liked=!p.liked;p.likes+=p.liked?1:-1;render();},
    comment:id=>modal('写一条评论',area('body','评论'),f=>{const body=C.text(f.get('body'),2000);if(!body)throw Error('评论不能为空');w.posts.find(p=>p.id===id).comments.push({author:profile().name,body,day:w.day});}),
    npcPost:()=>{const a=w.artists[Math.floor(Math.random()*w.artists.length)];if(!a)throw Error('请先添加画师');w.posts.unshift({id:C.uid(),author:a.name,artistId:a.id,category:'生活',body:'整理了最近的创作笔记，想试试新的配色。也欢迎来聊聊你们的 OC！',day:w.day,asset:null,likes:0,liked:false,comments:[]});render();},
    aiPost:()=>modal('AI 画师动态',`<label>选择画师<select name="artist">${w.artists.map(a=>`<option value="${E(a.id)}">${E(a.name)}</option>`).join('')}</select></label>${field('idea','动态主题','最近的创作或生活小事')}`,async f=>{const a=w.artists.find(a=>a.id===f.get('artist'));const body=await completeSafe(w.settings.chat,'chat',[{role:'user',content:`扮演虚拟画师 ${a.name}。人设：${a.linked?.personality||a.personality}。画风：${a.style}。剧情日 ${w.day}，写一条不超过 200 字的朋友圈动态，主题：${C.text(f.get('idea'))}。只返回正文，不声称改变订单或已提交图片。`}]);w.posts.unshift({id:C.uid(),author:a.name,artistId:a.id,category:'生活',body:C.text(body,3000),day:w.day,asset:null,likes:0,liked:false,comments:[]});},'生成并发布'),
    switchRole:()=>{if(w.role==='client'&&!w.artistActivated){confirmModal('✎ 你好，新画师！','启用后将创建独立画师身份，拥有自己的主页、钱包和收件箱，还能收到模拟客户的约稿。酒馆当前角色保持原样。',()=>{w.artistActivated=true;w.role='artist';C.incoming(w);});}else{w.role=w.role==='client'?'artist':'client';render();}},
    incoming:()=>{C.incoming(w);go('bench');},
    editAccount:()=>{const p=profile();modal('编辑身份资料',`${field('name','昵称',p.name)}${area('bio','简介',p.bio)}<label>头像<input type="file" name="file" accept="image/*"></label>${w.role==='artist'?field('min','最低报价',p.min,'number')+field('max','最高报价',p.max,'number')+field('days','工期（剧情日）',p.days,'number')+field('revisions','修改次数',p.revisions,'number'):''}`,async f=>{const name=C.text(f.get('name'),50);if(!name)throw Error('昵称不能为空');const update={name,bio:C.text(f.get('bio'),4000)};const file=f.get('file');if(file?.size)update.avatar=await putAssetSafe(file,file.name);if(w.role==='artist'){update.min=C.integer(f.get('min'),1);update.max=C.integer(f.get('max'),update.min);update.days=C.integer(f.get('days'),1,365);update.revisions=C.integer(f.get('revisions'),0,30);}Object.assign(p,update);if(w.settings.sharedProfile)Object.assign(w.accounts[w.role==='client'?'artist':'client'],{name:p.name,bio:p.bio,avatar:p.avatar});});},
    wallet:()=>modal('虚拟钱包账本',`<p>当前余额 ${money(profile().balance)} 绘币。初始赠送仅用于模拟。</p>${w.ledger.filter(l=>l.role===w.role).slice().reverse().map(l=>`<div class="hy-ledger"><span>${E(l.reason)}<small>第 ${l.day} 日</small></span><strong>${l.delta>0?'+':''}${l.delta}</strong><small>余额 ${l.balance}</small></div>`).join('')||empty('还没有交易记录')}`),
    retryDM:id=>aiReply(id),manualReply:id=>modal('手动扮演对方',area('body','对方的回复'),f=>{C.message(w,id,w.role,f.get('body'),{from:id==='self'?'client':'artist'});}),
    accountStyle:styleModal,bridge:bridgeModal,
    applyBridge:id=>{const e=w.bridge.find(e=>e.id===id),os=w.commissions.filter(o=>o.artistId===e.artistId&&o.status==='working');if(!os.length)throw Error('没有对应的绘制中订单，请先创建订单');modal('确认聊天同步事件',`<p>${E(e.body)}</p><label>对应订单<select name="order">${os.map(o=>`<option value="${E(o.id)}">${E(o.title)}</option>`).join('')}</select></label><p class="hy-muted">确认后仅建立稿件占位，不自动调用 API。</p>`,f=>B.applyCandidate(w,id,f.get('order')));},
    dismissBridge:id=>{w.bridge.find(e=>e.id===id).status='dismissed';bridgeModal();},undoBridge:id=>{B.undoCandidate(w,id);bridgeModal();},
    npc:()=>modal('提取角色卡与世界书 NPC','<p>将读取当前角色卡及其关联世界书的文字，交给所选私信 AI 提取人物。返回候选后由你勾选，已有画师不会自动覆盖。</p>',async()=>{const candidates=await B.npcCandidates(w);setTimeout(()=>modal('确认要添加的 NPC',candidates.map((a,i)=>check('npc'+i,`${a.name} · ${a.personality.slice(0,100)}`,false)).join('')||'<p>没有提取到人物。</p>',f=>{candidates.forEach((a,i)=>{if(f.has('npc'+i))w.artists.push(C.artist(a));});}),30);},'读取并提取'),
    bindChat:async()=>{const c=A.context();if(!c?.getCurrentChatId?.())throw Error('请先打开并保存一个酒馆聊天');await persist();if(!c.chatMetadata.huiyue)c.chatMetadata.huiyue={worldId:C.uid()};await c.saveMetadata();await switchWorld(c.chatMetadata.huiyue.worldId);toast('已打开当前聊天专属世界；原独立世界仍保留');},
    globalWorld:()=>switchWorld(globalId),
    export:()=>S.exportWorld(w),
    exportOrder:async id=>{const o=getOrder(id),copy=C.newWorld();copy.commissions=[structuredClone(o)];copy.artists=structuredClone(w.artists.filter(a=>a.id===o.artistId));copy.day=w.day;copy.accounts=structuredClone(w.accounts);copy.messages={};await S.exportWorld(copy);toast('订单包已导出，可独立恢复浏览；不会自动合并进其他世界');},
    import:()=>confirmModal('恢复完整存档','将用所选存档替换当前世界。建议先导出当前世界留作备份；其他聊天世界不会改变。',async()=>{const target=w.id,started=epoch;const f=await pickFile('application/json,.json');if(!f||started!==epoch)return;await saveChain;const restored=await S.importWorld(f,target);if(started!==epoch)return;abortAll();epoch++;w=restored;route={page:'home'};toast('存档和图片已恢复');}),
    reset:()=>confirmModal('重置当前世界','将清空当前世界的订单、画师和平台活动并重新开始。请先导出存档保留原图和资料。其他世界不受影响。',()=>{abortAll();epoch++;w=C.newWorld(w.id);route={page:'home'};}),
    createProject:()=>modal('发布企划',`${field('title','企划标题')}${area('brief','角色设定与画面需求')}${field('budget','预算（绘币）',800,'number')}${field('deadline','截稿剧情日',w.day+14,'number')}`,f=>{if(!C.text(f.get('title'))||!C.text(f.get('brief')))throw Error('请填写标题与需求');w.projects.unshift({id:C.uid(),title:C.text(f.get('title'),100),brief:C.text(f.get('brief')),budget:C.integer(f.get('budget'),1),deadline:C.integer(f.get('deadline'),w.day+1),applicants:[]});}),
    simulateApplicants:id=>{const p=w.projects.find(p=>p.id===id);if(p.deadline<=w.day)throw Error('企划已经截稿');p.applicants=w.artists.filter(a=>a.open&&a.available<=w.day&&a.min<=p.budget).map(a=>a.id);C.notify(w,`企划「${p.title}」收到 ${p.applicants.length} 份应征`);render();},
    applicants:id=>{const p=w.projects.find(p=>p.id===id);modal('企划画师与应征',`${w.artists.map(a=>`<div class="hy-ledger"><span>${E(a.name)} ${p.applicants.includes(a.id)?tag('已应征'):''}</span>${btn('inviteProject','邀请约稿',p.id+':'+a.id)}</div>`).join('')}`);},
    inviteProject:id=>{const [pid,aid]=id.split(':');const p=w.projects.find(p=>p.id===pid);quoteForm(aid,p);}
};
async function autoQueue(ids){const started=epoch;for(const id of ids){if(started!==epoch)break;while(started===epoch&&[...running.values()].some(t=>t.kind!=='dm'))await new Promise(r=>setTimeout(r,300));if(started!==epoch)break;try{const {o}=C.findVersion(w,id);if(automation(o,'autoPrompt'))startTask(id,'prompt');}catch(e){toast(e.message,true);}}}
function abortAll(){for(const t of running.values())t.controller.abort();running.clear();}
async function switchWorld(id){closeModal();abortAll();epoch++;const loadEpoch=epoch;if(w)await saveChain.catch(()=>{});const loaded=await S.loadWorld(id)||C.newWorld(id);if(loadEpoch!==epoch)return;w=loaded;for(const o of w.commissions)for(const v of o.versions)if(['prompting','drawing'].includes(v.status))v.status=v.asset?'ready':v.positive?'prompted':'empty';route={page:'home'};await persist();render();}
async function handleAction(e){const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();const act=b.dataset.act;if(!actions[act])return;try{await actions[act](b.dataset.id);if(w)await persist();if(!app.querySelector('.hy-modal'))render();}catch(err){toast(err.message,true);}}
app.addEventListener('click',handleAction);
app.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const data=new FormData(f);try{switch(f.dataset.form){case 'search':search=C.text(data.get('q'),100);render();break;
    case 'dm':{const body=C.text(data.get('body'));if(!body)return;const id=route.id;C.message(w,id,w.role,body,{from:'user'});await persist();render();aiReply(id);break;}
    case 'settings':{const next=structuredClone(w.settings);for(const k of ['autoPrompt','autoImage','randomEvents','sharedProfile'])next[k]=data.has(k);for(const kind of ['chat','prompt','image']){for(const k of ['mode','url','model',...(kind==='image'?[]:['template'])])next[kind][k]=C.text(data.get(`${kind}.${k}`),k==='template'?10000:1000);if(next[kind].mode==='openai'){const u=new URL(next[kind].url);if(!['http:','https:'].includes(u.protocol))throw Error('API 地址无效');}const key=data.get(`${kind}.key`);if(key)A.setKey(kind,key);}
        next.image.width=C.integer(data.get('width'),256,4096);next.image.height=C.integer(data.get('height'),256,4096);next.image.steps=C.integer(data.get('steps'),1,150);const cfg=Number(data.get('cfg'));if(!Number.isFinite(cfg)||cfg<0||cfg>40)throw Error('CFG 请输入 0–40');next.image.cfg=cfg;w.settings=next;await persist();toast('设置已保存；密钥仅保留在当前页面内存中');render();break;}
}}catch(err){toast(err.message,true);}});
launcher.addEventListener('click',async()=>{try{if(!w)await switchWorld(A.context()?.chatMetadata?.huiyue?.worldId||globalId);app.hidden=false;launcher.hidden=true;opened=true;render();}catch(e){toast('无法打开本地数据库：'+e.message,true);}});
function renderChatCards(){document.querySelectorAll('.hy-st-card').forEach(e=>e.remove());const c=A.context();if(!w?.settings.bridgeEnabled||!c)return;const chatId=c.getCurrentChatId?.()||'';for(const log of w.bridge.filter(x=>x.status==='applied'&&x.chatId===chatId)){const el=document.querySelector(`.mes[mesid="${Number(log.messageId)}"] .mes_text`);if(el){const card=document.createElement('button');card.className='hy-st-card';card.type='button';card.textContent='✿ 绘约 · 打开已同步的稿件';card.addEventListener('click',()=>{app.hidden=false;opened=true;launcher.hidden=true;go('order',log.orderId);});el.insertAdjacentElement('afterend',card);}}}
function hookTavern(){const c=A.context();if(!c)return;const types=c.eventTypes||c.event_types;
    c.eventSource?.on(types.CHAT_CHANGED,async()=>{try{const id=A.context()?.chatMetadata?.huiyue?.worldId||globalId;await switchWorld(id);}catch(e){toast(e.message,true);}});
    c.eventSource?.on(types.MESSAGE_RECEIVED,async id=>{if(!w)return;if(B.detectChatEvent(w,id)){await persist();if(opened&&['me','inbox'].includes(route.page))render();toast('绘约发现交稿话语，请在「我的 → 剧情同步」确认');}});
    for(const type of [types.MESSAGE_UPDATED,types.CHARACTER_MESSAGE_RENDERED,types.MORE_MESSAGES_LOADED].filter(Boolean))c.eventSource?.on(type,()=>renderChatCards());
    if(c.SlashCommandParser&&c.SlashCommand){c.SlashCommandParser.addCommandObject(c.SlashCommand.fromProps({name:'huiyue',callback:async()=>{launcher.click();return '';},helpString:'打开绘约虚拟约稿平台。'}));}
    const mount=document.querySelector('#extensions_settings2')||document.querySelector('#extensions_settings');if(mount){const panel=document.createElement('div');panel.className='extension_container';const b=document.createElement('button');b.textContent='✿ 打开绘约';b.className='menu_button';b.onclick=()=>launcher.click();panel.append(b);mount.append(panel);}
}
globalThis.Huiyue={version:'1.0.0',open:()=>launcher.click(),registerImageAdapter:A.registerImageAdapter};
hookTavern();
if(!A.context())launcher.click();
else switchWorld(A.context()?.chatMetadata?.huiyue?.worldId||globalId).catch(e=>toast(e.message,true));
window.addEventListener('beforeunload',()=>{for(const u of urls.values())URL.revokeObjectURL(u);});
